from typing import Optional, Any


class Pipeline:
    """
    High-level workflow manager for VisionFlow.

    Dataset -> Training -> Optimization -> Evaluation -> Deployment
    """

    def __init__(
        self,
        name: str = "VisionFlow Pipeline",
        config: Optional[dict] = None
    ):
        self.name = name
        self.config = config or {}

        # Main pipeline components
        self.dataset = None
        self.model = None

        # Results generated by different stages
        self.training_result = None
        self.optimization_result = None
        self.evaluation_result = None
        self.deployment_result = None

        # Pipeline state
        self.status = "created"

    def add_dataset(self, dataset):
        """Register a Dataset with the pipeline."""
        if dataset is None:
            raise ValueError("Dataset cannot be None")

        self.dataset = dataset
        self.status = "dataset_added"
        return self

    def set_model(self, model):
        """Register a Model with the pipeline."""
        if model is None:
            raise ValueError("Model cannot be None")

        self.model = model
        self.status = "model_added"
        return self

    def train(self, **kwargs):
        """Train the configured model using the registered dataset."""
        if self.model is None:
            raise ValueError("Model not found")
        if self.dataset is None:
            raise ValueError("Dataset not found")

        self.training_result = self.model.train(dataset=self.dataset, **kwargs)
        self.status = "trained"
        return self.training_result

    def optimize(self, **kwargs):
        """Optimize the trained model."""
        if self.model is None:
            raise ValueError("Model not found")
        if self.training_result is None:
            raise ValueError("Model has not been trained")

        self.optimization_result = self.model.optimize(**kwargs)
        self.status = "optimized"
        return self.optimization_result

    def evaluate(self, **kwargs):
        """Evaluate the current model."""
        if self.model is None:
            raise ValueError("Model not found")

        self.evaluation_result = self.model.evaluate(**kwargs)
        self.status = "evaluated"
        return self.evaluation_result

    def deploy(self, **kwargs):
        """Prepare the validated model for deployment."""
        if self.model is None:
            raise ValueError("Model not found")
        if self.evaluation_result is None:
            raise ValueError("Model has not been evaluated")

        self.deployment_result = self.model.deploy(**kwargs)
        self.status = "deployed"
        return self.deployment_result

    def run(self):
        """
        Execute the complete workflow:
        prepare -> analyze -> train -> optimize -> evaluate -> deploy
        """
        if self.dataset is None:
            raise ValueError("Dataset not found")
        if self.model is None:
            raise ValueError("Model not found")

        self.dataset.prepare()
        self.dataset.analyze()
        self.train()
        self.optimize()
        self.evaluate()
        self.deploy()

        self.status = "completed"
        return self

    def summary(self):
        """Return the current pipeline state."""
        return {
            "name": self.name,
            "status": self.status,
            "dataset": self.dataset,
            "model": self.model,
            "training": self.training_result,
            "optimization": self.optimization_result,
            "evaluation": self.evaluation_result,
            "deployment": self.deployment_result
        }